import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameTick;

import static org.mockito.Mockito.*;

/** Uses real instance-coordinate conversion, with a single unrotated template chunk. */
final class PluginEventFixture
{
	final Client client = mock(Client.class);
	final Player local = mock(Player.class);
	final WorldView world = mock(WorldView.class);
	final SoundManager sounds = mock(SoundManager.class);
	final BeepDeepPlugin plugin = new BeepDeepPlugin();

	PluginEventFixture()
	{
		Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				bind(Client.class).toInstance(client);
				bind(SoundManager.class).toInstance(sounds);
			}
		}).injectMembers(plugin);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(local);
		when(client.getTopLevelWorldView()).thenReturn(world);
		when(client.getWorldView(anyInt())).thenReturn(world);
		when(world.isInstance()).thenReturn(true);
		LocalPoint location = LocalPoint.fromScene(1, 1, world);
		when(local.getLocalLocation()).thenReturn(location);
	}

	void region(int region)
	{
		int chunkX = (region >> 8) * 8;
		int chunkY = (region & 255) * 8;
		when(world.getInstanceTemplateChunks()).thenReturn(new int[][][]{{{chunkX << 14 | chunkY << 3}}});
	}

	void ticks(int count)
	{
		for (int i = 0; i < count; i++)
		{
			plugin.onGameTick(new GameTick());
		}
	}
}

package com.beepdeep;

import java.util.Arrays;
import java.util.Collection;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import static org.mockito.Mockito.*;

@RunWith(Parameterized.class)
public class PuzzleRoomTransitionTest
{
	@Parameterized.Parameters(name = "{1}")
	public static Collection<Object[]> rooms()
	{
		return Arrays.asList(new Object[][]{
			{15698, ToaEvent.CRONDIS_ENTER, ToaEvent.CRONDIS_LEAVE},
			{15186, ToaEvent.APMEKEN_ENTER, ToaEvent.APMEKEN_LEAVE},
			{14162, ToaEvent.SCABARAS_ENTER, ToaEvent.SCABARAS_LEAVE},
			{14674, ToaEvent.HET_ENTER, ToaEvent.HET_LEAVE}
		});
	}

	private final int region;
	private final ToaEvent enter;
	private final ToaEvent leave;

	public PuzzleRoomTransitionTest(int region, ToaEvent enter, ToaEvent leave)
	{
		this.region = region;
		this.enter = enter;
		this.leave = leave;
	}

	@Test
	public void walkingWithinRoomIsSilentAndReentryPlaysAgain()
	{
		PluginEventFixture f = new PluginEventFixture();
		f.region(region);
		f.ticks(3);
		verify(f.sounds).trigger(enter);
		verifyNoMoreInteractions(f.sounds);
		f.region(15188); // Ba-Ba is not a puzzle room.
		f.ticks(2);
		verify(f.sounds).trigger(leave);
		verifyNoMoreInteractions(f.sounds);
		f.region(region);
		f.ticks(2);
		verify(f.sounds, times(2)).trigger(enter);
		verifyNoMoreInteractions(f.sounds);
	}
}

