		when(table.iterator()).thenAnswer(invocation -> Arrays.asList(animations).iterator());
		return table;
	}
}

package com.beepdeep;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.concurrent.CompletableFuture;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SoundDownloadResponseTest
{
	private static final String URL = "https://example.com/sound.aiff?token=1";
	@Rule
	public TemporaryFolder temporary = new TemporaryFolder(new File("build"));
	private OkHttpClient http;
	private Call call;
	private SoundFileResolver resolver;
	private File cache;

	@Before
	public void setUp() throws IOException
	{
		http = mock(OkHttpClient.class);
		call = mock(Call.class);
		when(http.newCall(any())).thenReturn(call);
		cache = temporary.newFolder();
		resolver = new SoundFileResolver(http, cache);
		resolver.startUp();
	}

	@After
	public void tearDown()
	{
		resolver.shutDown();
	}

	@Test
	public void successfulResponsePublishesBytesAndCanBeFoundByUrl() throws Exception
	{
		byte[] bytes = {1, 2, 3, 4};
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		ResponseBody body = ResponseBody.create(MediaType.parse("audio/aiff"), bytes);
		callback().onResponse(call, response(200, body));
		File file = result.join();
		assertNotNull(file);
		assertEquals(cache.getCanonicalFile(), file.getParentFile().getCanonicalFile());
		assertTrue(file.getName().matches("[a-f0-9]{64}\\.aiff"));
		assertArrayEquals(bytes, Files.readAllBytes(file.toPath()));
		assertEquals(file, resolver.cachedFile(URL));
		assertNull(resolver.cachedFile(URL + "2")); // Query is part of the cache key.
		assertEquals(1, cache.list().length);
		ArgumentCaptor<Request> request = ArgumentCaptor.forClass(Request.class);
		verify(http).newCall(request.capture());
		assertEquals(URL, request.getValue().url().toString());
		verify(call, never()).execute();
	}

	@Test
	public void httpErrorClosesBodyDoesNotReadItAndAllowsRetry() throws Exception
	{
		BufferedSource source = mock(BufferedSource.class);
		ResponseBody body = body(source, 0);
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(404, body));
		assertNull(result.join());
		verify(source).close();
		verify(source, never()).inputStream();
		assertEquals(0, cache.list().length);
		assertNotSame(result, resolver.download(URL, () -> true));
		verify(http, times(2)).newCall(any());
	}

	@Test
	public void declaredOversizeBodyIsRejectedBeforeReading() throws Exception
	{
		BufferedSource source = mock(BufferedSource.class);
		ResponseBody body = body(source, SoundFileResolver.MAX_DOWNLOAD_BYTES + 1);
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(200, body));
		assertNull(result.join());
		verify(source, never()).inputStream();
		verify(source).close();
		assertEquals(0, cache.list().length);
	}

	@Test
	public void emptyBodyDoesNotBecomeACacheHit() throws Exception
	{
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(200, ResponseBody.create(null, new byte[0])));
		assertNull(result.join());
		assertNull(resolver.cachedFile(URL));
		assertEquals(0, cache.list().length);
	}

	@Test
	public void bodyReadFailureLeavesNoPartialCacheAndCanRetry() throws Exception
	{
		BufferedSource source = mock(BufferedSource.class);
		ResponseBody body = body(source, -1);
		java.io.InputStream input = mock(java.io.InputStream.class);
		when(source.inputStream()).thenReturn(input);
		when(input.read(any(byte[].class))).thenThrow(new IOException("Connection reset"));
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(200, body));
		assertNull(result.join());
		verify(input).close();
		verify(source).close();
		assertEquals(0, cache.list().length);
		assertNotSame(result, resolver.download(URL, () -> true));
	}

	@Test
	public void canceledResponseCannotPublishBytes() throws Exception
	{
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		when(call.isCanceled()).thenReturn(true);
		callback().onResponse(call, response(200, ResponseBody.create(null, new byte[]{1})));
		assertNull(result.join());
		assertEquals(0, cache.list().length);
	}

	private Callback callback()
	{
		ArgumentCaptor<Callback> callback = ArgumentCaptor.forClass(Callback.class);
		verify(call).enqueue(callback.capture());
		return callback.getValue();
	}

	private ResponseBody body(BufferedSource source, long length)
	{
		return new ResponseBody()
		{
			@Override
			public MediaType contentType()
			{
				return null;
			}

			@Override
			public long contentLength()
			{
				return length;
			}

			@Override
			public BufferedSource source()
			{
				return source;
			}
		};
	}

	private Response response(int code, ResponseBody body)
	{
		return new Response.Builder().request(new Request.Builder().url(URL).build())
			.protocol(Protocol.HTTP_1_1).code(code).message("Test response").body(body).build();
	}
}

package com.beepdeep;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okio.Timeout;
import org.junit.Test;

import static org.junit.Assert.*;

public class SoundFileResolverLifecycleTest
{
	@Test
	public void duplicateDownloadsShareRequestAndShutdownCancelsIt()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		CompletableFuture<File> result = resolver.download("https://example.com/sound.wav", () -> true);
		assertSame(result, resolver.download("https://example.com/sound.wav", () -> true));
		assertEquals(1, http.calls.size());
		resolver.shutDown();
		assertTrue(http.calls.get(0).isCanceled());
		assertTrue(result.isCancelled());
		assertNull(resolver.download("https://example.com/sound.wav", () -> true).join());
	}

	@Test
	public void failedDownloadCanBeRetried()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		try
		{
			CompletableFuture<File> result = resolver.download("https://example.com/sound.wav", () -> true);
			http.calls.get(0).fail();
			assertNull(result.join());
			assertNotSame(result, resolver.download("https://example.com/sound.wav", () -> true));
			assertEquals(2, http.calls.size());
		}
		finally
		{
			resolver.shutDown();
		}
	}

	@Test
	public void staleFailureDoesNotRemoveDownloadFromNewSession()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		resolver.download("https://example.com/sound.wav", () -> true);
		resolver.shutDown();
		resolver.startUp();
		try
		{
			CompletableFuture<File> current = resolver.download("https://example.com/sound.wav", () -> true);
			http.calls.get(0).fail();
			assertSame(current, resolver.download("https://example.com/sound.wav", () -> true));
			assertEquals(2, http.calls.size());
		}
		finally
		{
			resolver.shutDown();
		}
	}

	@Test
	public void inactiveSessionAndInvalidUrlDoNotStartRequests()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		try
		{
			assertNull(resolver.download("https://example.com/sound.wav", () -> false).join());
			assertNull(resolver.download("https://", () -> true).join());
			assertTrue(http.calls.isEmpty());
		}
		finally
		{
			resolver.shutDown();
		}
	}

	private static final class RecordingClient extends OkHttpClient
	{
		private final List<PendingCall> calls = new ArrayList<>();

		@Override
		public Call newCall(Request request)
		{
			PendingCall call = new PendingCall(request);
			calls.add(call);
			return call;
		}
	}

	private static final class PendingCall implements Call
	{
		private final Request request;
		private Callback callback;
		private boolean canceled;

		private PendingCall(Request request)
		{
			this.request = request;
		}

		void fail()
		{
			callback.onFailure(this, new IOException("Simulated download failure"));
		}

		@Override
		public Request request()
		{
			return request;
		}

		@Override
		public Response execute()
		{
			throw new UnsupportedOperationException("Tests require asynchronous requests");
		}

		@Override
		public void enqueue(Callback callback)
		{
			this.callback = callback;
		}

		@Override
		public void cancel()
		{
			canceled = true;
		}

		@Override
		public boolean isExecuted()
		{
			return callback != null;
		}

		@Override
		public boolean isCanceled()
		{
			return canceled;
		}

		@Override
		public Timeout timeout()
		{
			return new Timeout();
		}

		@Override
		public Call clone()
		{
			return new PendingCall(request);
		}
	}
}

package com.beepdeep;

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Locale;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;

public class SoundFileResolverTest
{
	@Rule
	public TemporaryFolder temporary = new TemporaryFolder(new File("build"));

	@Test
	public void remoteSchemeDetectionIsLocaleIndependent()
	{
		Locale previous = Locale.getDefault();
		try
		{
			Locale.setDefault(new Locale("tr", "TR"));
			assertTrue(SoundFileResolver.isRemote("HTTPS://example.com/sound.wav"));
			assertFalse(SoundFileResolver.isRemote("beep-deep/sounds/alert.wav"));
		}
		finally
		{
			Locale.setDefault(previous);
		}
	}

	@Test
	public void cacheExtensionIgnoresQueryAndFragment()
	{
		assertEquals(".aiff", SoundFileResolver.extensionOf("https://example.com/sound.aiff?token=1#clip"));
		assertEquals(".wav", SoundFileResolver.extensionOf("https://example.com/audio"));
		assertEquals(".wav", SoundFileResolver.extensionOf("https://example.com/sound.bad%20"));
	}

	@Test
	public void localFilesResolveRelativeAndAbsolutePathsInsideRoot() throws IOException
	{
		Path root = temporary.newFolder().toPath();
		Path sounds = Files.createDirectories(root.resolve("beep-deep/sounds"));
		Path sound = Files.write(sounds.resolve("sound.wav"), new byte[]{1});
		assertEquals(sound.toRealPath().toFile(), SoundFileResolver.localFile(root, "beep-deep/sounds/sound.wav"));
		assertEquals(sound.toRealPath().toFile(), SoundFileResolver.localFile(root, sound.toAbsolutePath().toString()));
	}

	@Test
	public void externalAbsolutePathsWorkWithoutAnExistingRuneLiteDirectory() throws IOException
	{
		Path root = temporary.newFolder().toPath().resolve("missing-runelite");
		Path outside = temporary.newFile("external sound.wav").toPath().toRealPath();
		assertEquals(outside.toFile(), SoundFileResolver.localFile(root, outside.toString()));
		assertThrowsIo(() -> SoundFileResolver.localFile(root, outside.getParent().toString()));
		assertThrowsIo(() -> SoundFileResolver.localFile(root, outside.resolveSibling("missing.wav").toString()));
	}

	@Test
	public void localFilesRejectDirectoryTraversal() throws IOException
	{
		Path root = temporary.newFolder().toPath();
		File outside = temporary.newFile();
		assertThrowsIo(() -> SoundFileResolver.localFile(root, "../" + outside.getName()));
		assertThrowsIo(() -> SoundFileResolver.localFile(root, "."));
	}

	@Test
	public void completeDownloadReplacesCacheAndRemovesTemporaryFile() throws IOException
	{
		Path target = temporary.newFolder().toPath().resolve("sound.wav");
		Files.write(target, new byte[]{9});
		SoundFileResolver.writeToCache(new ByteArrayInputStream(new byte[]{1, 2, 3}), target, () -> false);
		assertArrayEquals(new byte[]{1, 2, 3}, Files.readAllBytes(target));
		assertOnlyTargetRemains(target);
	}

	@Test
	public void emptyOrCanceledDownloadPreservesExistingCache() throws IOException
	{
		Path target = temporary.newFolder().toPath().resolve("sound.wav");
		Files.write(target, new byte[]{9});
		assertThrowsIo(() -> SoundFileResolver.writeToCache(new ByteArrayInputStream(new byte[0]), target, () -> false));
		assertThrowsIo(() -> SoundFileResolver.writeToCache(new ByteArrayInputStream(new byte[]{1}), target, () -> true));
		assertArrayEquals(new byte[]{9}, Files.readAllBytes(target));
		assertOnlyTargetRemains(target);
	}

	@Test
	public void failedStreamPreservesCacheAndRemovesTemporaryFile() throws IOException
	{
		Path target = temporary.newFolder().toPath().resolve("sound.wav");
		Files.write(target, new byte[]{9});
		InputStream broken = new InputStream()
		{
			@Override
			public int read() throws IOException
			{
				throw new IOException("Simulated read failure");
			}
		};
		assertThrowsIo(() -> SoundFileResolver.writeToCache(broken, target, () -> false));
		assertArrayEquals(new byte[]{9}, Files.readAllBytes(target));
		assertOnlyTargetRemains(target);
	}

	@Test
	public void oversizedStreamIsRejectedWithoutPublishing() throws IOException
	{
		Path target = temporary.newFolder().toPath().resolve("sound.wav");
		InputStream oversized = new InputStream()
		{
			private long remaining = SoundFileResolver.MAX_DOWNLOAD_BYTES + 1;

			@Override
			public int read()
			{
				return remaining-- > 0 ? 0 : -1;
			}

			@Override
			public int read(byte[] buffer, int offset, int length)
			{
				if (remaining == 0)
				{
					return -1;
				}
				int count = (int) Math.min(remaining, length);
				remaining -= count;
				return count;
			}
		};
		assertThrowsIo(() -> SoundFileResolver.writeToCache(oversized, target, () -> false));
		assertFalse(Files.exists(target));
		assertEquals(0, target.getParent().toFile().list().length);
	}

	private static void assertOnlyTargetRemains(Path target)
	{
		assertArrayEquals(new String[]{target.getFileName().toString()}, target.getParent().toFile().list());
	}

	private static void assertThrowsIo(IoAction action) throws IOException
	{
		try
		{
			action.run();
			fail("Expected IOException");
		}
		catch (IOException expected)
		{
			// Expected failure.
		}
	}

	private interface IoAction
	{
		void run() throws IOException;
	}
}

package com.beepdeep;

import java.io.File;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import net.runelite.client.audio.AudioPlayer;
import org.junit.Test;

import static org.junit.Assert.*;

public class SoundManagerLifecycleTest
{
	@Test
	public void callbackFromPreviousSessionCannotPlayAfterRestart() throws Exception
	{
		RecordingAudio audio = new RecordingAudio();
		PendingResolver resolver = new PendingResolver();
		SoundManager manager = new SoundManager(null, audio, resolver, remoteConfig(50));
		try
		{
			manager.startUp();
			manager.trigger(ToaEvent.CRONDIS_ENTER);
			CompletableFuture<File> oldDownload = resolver.requested.get(2, TimeUnit.SECONDS);
			manager.shutDown();
			manager.startUp();
			oldDownload.complete(new File("old.wav"));

			resolver.requested = new CompletableFuture<>();
			manager.trigger(ToaEvent.CRONDIS_ENTER);
			resolver.requested.get(2, TimeUnit.SECONDS).complete(new File("new.wav"));
			assertEquals("new.wav", audio.played.get(2, TimeUnit.SECONDS).getName());
			assertEquals(1, audio.count.get());
		}
		finally
		{
			manager.shutDown();
		}
	}

	@Test
	public void mutedSoundDoesNotStartDownload()
	{
		PendingResolver resolver = new PendingResolver();
		SoundManager manager = new SoundManager(null, new RecordingAudio(), resolver, remoteConfig(0));
		try
		{
			manager.startUp();
			manager.trigger(ToaEvent.CRONDIS_ENTER);
			assertFalse(resolver.requested.isDone());
		}
		finally
		{
			manager.shutDown();
		}
	}

	@Test
	public void stoppedManagerIgnoresTriggers()
	{
		PendingResolver resolver = new PendingResolver();
		SoundManager manager = new SoundManager(null, new RecordingAudio(), resolver, remoteConfig(50));
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		assertFalse(resolver.requested.isDone());
	}

	private static BeepDeepConfig remoteConfig(int volume)
	{
		return new BeepDeepConfig()
		{
			@Override
			public boolean enableRemoteUrls()
			{
				return true;
			}

			@Override
			public String crondisEnterSound1()
			{
				return "https://example.com/sound.wav";
			}

			@Override
			public int crondisEnterVolume1()
			{
				return volume;
			}
		};
	}

	private static final class PendingResolver extends SoundFileResolver
	{
		private volatile CompletableFuture<CompletableFuture<File>> requested = new CompletableFuture<>();

		private PendingResolver()
		{
			super(null);
		}

		@Override
		File cachedFile(String url)
		{
			return null;
		}

		@Override
		synchronized CompletableFuture<File> download(String url, BooleanSupplier active)
		{
			CompletableFuture<File> result = new CompletableFuture<>();
			requested.complete(result);
			return result;
		}
	}

	private static final class RecordingAudio extends AudioPlayer
	{
		private final AtomicInteger count = new AtomicInteger();
		private final CompletableFuture<File> played = new CompletableFuture<>();

		@Override
		public void play(File file, float gain)
		{
			count.incrementAndGet();
			played.complete(file);
		}
	}
}

